class Produk {
  nama: string;
  harga: number;
  terjual = 0;

  constructor(nama: string, harga: number) {
    this.nama = nama;
    this.harga = harga;
  }
  jual(jumlah: number): number {
    this.terjual += jumlah;
    return this.harga * jumlah;
  }
}
const kopi = new Produk("Kopi Susu", 18000);
console.log(kopi.jual(2));
kopi.jual(3);
console.log(kopi.nama, "terjual", kopi.terjual);

