class Rekening {
  pemilik: string;
  saldo = 0;
  constructor(pemilik: string) {
    this.pemilik = pemilik;
  }
  setor(jumlah: number): void {
    this.saldo += jumlah;
  }
  tarik(jumlah: number): void {
    this.saldo -= jumlah;
  }
}
const rina = new Rekening("Rina");
rina.setor(50000);
console.log(rina.pemilik, rina.saldo);
rina.tarik(20000);
console.log(rina.pemilik, rina.saldo);

