cards.solution:
class Barang {
  nama: string;
  harga: number;
  stok = 0;
  constructor(nama: string, harga: number) {
    this.nama = nama;
    this.harga = harga;
  }
  tambahStok(n: number): void {
    this.stok += n;
  }
  nilaiStok(): number {
    return this.harga * this.stok;
  }
}
const gula = new Barang("Gula", 14000);
gula.tambahStok(3);
gula.tambahStok(2);
console.log(gula.nama, gula.nilaiStok());
